/* ===== CSS Variables ===== */
:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-tertiary: #16213e;
  --bg-card: #1e1e32;
  --bg-hover: #252542;
  --bg-surface: #222238;
  --border-color: #2a2a45;
  --border-light: #333358;
  --text-primary: #e8e8f0;
  --text-secondary: #a0a0b8;
  --text-muted: #6a6a82;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e4fdb;
  --accent-blue-bg: rgba(41, 98, 255, 0.12);
  --green: #00C853;
  --green-bg: rgba(0, 200, 83, 0.12);
  --red: #F7525F;
  --red-bg: rgba(247, 82, 95, 0.12);
  --gold: #FFB300;
  --gold-bg: rgba(255, 179, 0, 0.12);
  --teal: #00BCD4;
  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 16px;
  --spacing-lg: 24px;
  --spacing-xl: 32px;
  --spacing-2xl: 48px;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --font-xs: 11px;
  --font-sm: 12px;
  --font-md: 13px;
  --font-lg: 14px;
  --font-xl: 16px;
  --font-2xl: 20px;
  --font-3xl: 24px;
  --font-4xl: 32px;
  --font-5xl: 40px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.5);
}

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-blue); text-decoration: none; }
a:hover { text-decoration: underline; }
ul { list-style: none; }

img { max-width: 100%; display: block; }

/* ===== Typography ===== */
.text-green { color: var(--green); }
.text-red { color: var(--red); }
.text-muted { color: var(--text-muted); }
.text-accent { color: var(--accent-blue); }
.text-sm { font-size: var(--font-sm); }
.text-xs { font-size: var(--font-xs); }
.text-lg { font-size: var(--font-lg); }
.text-xl { font-size: var(--font-xl); }
.text-2xl { font-size: var(--font-2xl); }
.font-semibold { font-weight: 600; }
.font-bold { font-weight: 700; }

/* ===== Layout ===== */
.container { max-width: 1400px; margin: 0 auto; padding: 0 var(--spacing-lg); }
.section { padding: var(--spacing-2xl) 0; }
.section-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: var(--spacing-lg);
}
.section-title { font-size: var(--font-xl); font-weight: 700; }
.section-link { font-size: var(--font-sm); color: var(--accent-blue); cursor: pointer; }
.section-link:hover { text-decoration: underline; }

/* ===== Header / Navigation ===== */
.main-header {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky; top: 0; z-index: 100;
}
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: 1400px; margin: 0 auto; padding: 0 var(--spacing-lg);
  height: 56px;
}
.logo {
  display: flex; align-items: center; gap: var(--spacing-sm);
  font-size: var(--font-xl); font-weight: 800; color: var(--text-primary);
  letter-spacing: -0.5px;
}
.logo-icon {
  width: 32px; height: 32px; background: var(--accent-blue);
  border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 16px; font-weight: 700;
}
.logo-icon svg { width: 18px; height: 18px; }
.main-nav { display: flex; gap: 4px; }
.main-nav a {
  color: var(--text-secondary); font-size: var(--font-md); font-weight: 500;
  padding: 8px 16px; border-radius: var(--radius-md); transition: all 0.15s;
}
.main-nav a:hover, .main-nav a.active {
  color: var(--text-primary); background: var(--bg-hover); text-decoration: none;
}
.main-nav a.active { color: var(--accent-blue); }
.header-actions { display: flex; align-items: center; gap: var(--spacing-md); }
.btn {
  display: inline-flex; align-items: center; gap: var(--spacing-sm);
  padding: 8px 16px; border-radius: var(--radius-md); font-size: var(--font-md);
  font-weight: 600; cursor: pointer; border: none; transition: all 0.15s;
  font-family: inherit;
}
.btn-primary { background: var(--accent-blue); color: #fff; }
.btn-primary:hover { background: var(--accent-blue-hover); }
.btn-outline {
  background: transparent; color: var(--text-primary);
  border: 1px solid var(--border-color);
}
.btn-outline:hover { border-color: var(--text-muted); }
.btn-sm { padding: 6px 12px; font-size: var(--font-sm); }
.btn-xs { padding: 4px 8px; font-size: var(--font-xs); }
.btn-icon { width: 36px; height: 36px; padding: 0; justify-content: center; border-radius: var(--radius-md); }

/* ===== Tabs ===== */
.tab-bar {
  display: flex; gap: 2px; background: var(--bg-tertiary);
  border-radius: var(--radius-md); padding: 3px;
}
.tab-btn {
  padding: 6px 14px; border-radius: var(--radius-sm); font-size: var(--font-sm);
  font-weight: 500; cursor: pointer; border: none; background: transparent;
  color: var(--text-secondary); transition: all 0.15s; font-family: inherit;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active { background: var(--bg-primary); color: var(--text-primary); }
.tab-btn.ghost {
  background: none; color: var(--text-muted); font-size: var(--font-md);
  padding: 8px 0; margin-right: var(--spacing-lg); border-radius: 0;
  border-bottom: 2px solid transparent; font-weight: 600;
}
.tab-btn.ghost.active { color: var(--accent-blue); border-bottom-color: var(--accent-blue); }

/* ===== Cards ===== */
.card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: var(--spacing-lg);
}
.card-sm { padding: var(--spacing-md); border-radius: var(--radius-md); }
.card-hover:hover { border-color: var(--border-light); background: var(--bg-hover); }

/* ===== Market Summary Bar ===== */
.market-bar {
  display: flex; gap: 1px; background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color); overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.market-item {
  display: flex; align-items: center; gap: var(--spacing-sm);
  padding: 8px 14px; white-space: nowrap; cursor: pointer;
  font-size: var(--font-sm); border-right: 1px solid var(--border-color);
  min-width: 0; transition: background 0.15s;
}
.market-item:hover { background: var(--bg-hover); }
.market-item .ticker { font-weight: 700; font-size: var(--font-xs); color: var(--text-muted); }
.market-item .price { font-weight: 600; }
.market-item .change { font-size: var(--font-xs); padding: 2px 6px; border-radius: var(--radius-sm); }
.change-up { color: var(--green); background: var(--green-bg); }
.change-down { color: var(--red); background: var(--red-bg); }

/* ===== Stat Cards ===== */
.stat-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--spacing-md);
}
.stat-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: var(--spacing-lg);
}
.stat-label { font-size: var(--font-xs); color: var(--text-muted); margin-bottom: var(--spacing-xs); text-transform: uppercase; letter-spacing: 0.5px; }
.stat-value { font-size: var(--font-xl); font-weight: 700; }
.stat-change { font-size: var(--font-sm); margin-top: var(--spacing-xs); }

/* ===== Trends Grid ===== */
.trends-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: var(--spacing-sm);
}

/* ===== Tables ===== */
.data-table { width: 100%; border-collapse: collapse; }
.data-table th {
  text-align: left; font-size: var(--font-xs); color: var(--text-muted);
  font-weight: 500; padding: 8px 12px; text-transform: uppercase; letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border-color);
}
.data-table td {
  padding: 8px 12px; font-size: var(--font-md); border-bottom: 1px solid var(--border-color);
  font-variant-numeric: tabular-nums;
}
.data-table tr:hover td { background: var(--bg-hover); }
.data-table .symbol { font-weight: 600; color: var(--text-primary); }
.data-table .name { color: var(--text-secondary); font-size: var(--font-sm); }

/* ===== Sparkline ===== */
.sparkline { width: 80px; height: 30px; }
.sparkline canvas { width: 100%; height: 100%; }

/* ===== Watchlist Accordion ===== */
.watchlist { display: flex; flex-direction: column; }
.watchlist-group { border-bottom: 1px solid var(--border-color); }
.watchlist-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 14px; cursor: pointer; font-size: var(--font-sm);
  font-weight: 600; color: var(--text-secondary); transition: background 0.15s;
  user-select: none;
}
.watchlist-header:hover { background: var(--bg-hover); color: var(--text-primary); }
.watchlist-header .arrow { transition: transform 0.2s; font-size: 10px; }
.watchlist-header.open .arrow { transform: rotate(90deg); }
.watchlist-body { display: none; }
.watchlist-body.open { display: block; }
.watchlist-row {
  display: grid; grid-template-columns: 1fr 60px 50px; padding: 6px 14px 6px 24px;
  font-size: var(--font-sm); cursor: pointer; gap: var(--spacing-sm);
  align-items: center;
}
.watchlist-row:hover { background: var(--bg-hover); }
.watchlist-row .sym { font-weight: 600; }
.watchlist-row .price { text-align: right; font-variant-numeric: tabular-nums; }
.watchlist-row .chg { text-align: right; font-variant-numeric: tabular-nums; font-size: var(--font-xs); }

/* ===== Idea Cards ===== */
.idea-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: var(--spacing-md);
}
.idea-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); overflow: hidden; transition: all 0.15s;
}
.idea-card:hover { border-color: var(--border-light); transform: translateY(-2px); box-shadow: var(--shadow-md); }
.idea-card-header {
  display: flex; align-items: center; gap: var(--spacing-sm);
  padding: var(--spacing-md);
}
.idea-avatar {
  width: 40px; height: 40px; border-radius: 50%;
  background: var(--bg-tertiary); display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: var(--font-lg); color: var(--accent-blue);
}
.idea-user { font-weight: 600; font-size: var(--font-md); }
.idea-time { font-size: var(--font-xs); color: var(--text-muted); }
.idea-card-body { padding: 0 var(--spacing-md) var(--spacing-md); }
.idea-ticker { display: inline-block; padding: 3px 8px; border-radius: var(--radius-sm); font-weight: 700; font-size: var(--font-xs); margin-right: var(--spacing-sm); }
.idea-card-footer {
  display: flex; align-items: center; gap: var(--spacing-lg);
  padding: var(--spacing-sm) var(--spacing-md); border-top: 1px solid var(--border-color);
  font-size: var(--font-sm); color: var(--text-muted);
}
.idea-card-footer span { display: flex; align-items: center; gap: 4px; cursor: pointer; }
.idea-card-footer span:hover { color: var(--text-secondary); }
.idea-title { font-size: var(--font-md); font-weight: 600; margin-bottom: var(--spacing-sm); }
.idea-excerpt { font-size: var(--font-sm); color: var(--text-secondary); line-height: 1.6; }
.idea-chart-preview {
  height: 140px; background: var(--bg-tertiary); border-radius: var(--radius-md);
  margin-bottom: var(--spacing-sm); overflow: hidden;
}
.idea-chart-preview canvas { width: 100%; height: 100%; }
.idea-tag {
  display: inline-block; padding: 2px 8px; border-radius: var(--radius-sm);
  font-size: var(--font-xs); background: var(--accent-blue-bg); color: var(--accent-blue);
  margin-right: 4px;
}
.idea-badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 8px; border-radius: var(--radius-sm); font-size: var(--font-xs);
  font-weight: 600;
}
.badge-bullish { color: var(--green); background: var(--green-bg); }
.badge-bearish { color: var(--red); background: var(--red-bg); }

/* ===== Hero Sections ===== */
.hero {
  background: linear-gradient(135deg, var(--bg-secondary) 0%, #111133 50%, var(--bg-tertiary) 100%);
  padding: var(--spacing-2xl) 0;
}
.hero-inner { max-width: 800px; }
.hero h1 { font-size: var(--font-5xl); font-weight: 800; line-height: 1.15; margin-bottom: var(--spacing-lg); letter-spacing: -1px; }
.hero p { font-size: var(--font-lg); color: var(--text-secondary); margin-bottom: var(--spacing-xl); line-height: 1.7; }
.hero-actions { display: flex; gap: var(--spacing-md); }

/* ===== Chart Workspace ===== */
.chart-workspace {
  display: grid; grid-template-columns: 260px 1fr;
  height: calc(100vh - 56px); overflow: hidden;
}
.chart-sidebar {
  background: var(--bg-secondary); border-right: 1px solid var(--border-color);
  overflow-y: auto; display: flex; flex-direction: column;
}
.chart-main { display: flex; flex-direction: column; overflow: hidden; }
.chart-toolbar {
  display: flex; align-items: center; gap: var(--spacing-sm);
  padding: var(--spacing-sm) var(--spacing-md); border-bottom: 1px solid var(--border-color);
  background: var(--bg-secondary); flex-wrap: wrap;
}
.chart-toolbar .tool-group { display: flex; align-items: center; gap: 4px; }
.chart-toolbar .tool-divider { width: 1px; height: 24px; background: var(--border-color); margin: 0 var(--spacing-sm); }
.chart-canvas-area {
  flex: 1; position: relative; background: var(--bg-primary);
}
.chart-canvas-area canvas { width: 100%; height: 100%; position: absolute; top: 0; left: 0; }
.chart-detail-panel {
  background: var(--bg-secondary); border-top: 1px solid var(--border-color);
  padding: var(--spacing-md);
}
.price-display { display: flex; align-items: baseline; gap: var(--spacing-md); margin-bottom: var(--spacing-md); }
.price-display .current { font-size: var(--font-3xl); font-weight: 800; }
.price-display .change-amt { font-size: var(--font-lg); }
.price-display .change-pct { font-size: var(--font-lg); }
.detail-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--spacing-md);
}
.detail-item .label { font-size: var(--font-xs); color: var(--text-muted); }
.detail-item .value { font-size: var(--font-md); font-weight: 600; margin-top: 2px; }

/* ===== Timeframe Toggle ===== */
.timeframe-toggle {
  display: flex; gap: 2px; background: var(--bg-tertiary);
  border-radius: var(--radius-md); padding: 2px;
}
.timeframe-toggle button {
  padding: 4px 10px; border: none; background: transparent; color: var(--text-secondary);
  font-size: var(--font-xs); font-weight: 500; cursor: pointer; border-radius: 3px;
  font-family: inherit;
}
.timeframe-toggle button:hover { color: var(--text-primary); }
.timeframe-toggle button.active { background: var(--bg-primary); color: var(--text-primary); }

/* ===== Broker Cards ===== */
.broker-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: var(--spacing-md);
}
.broker-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: var(--spacing-lg); transition: all 0.15s;
}
.broker-card:hover { border-color: var(--accent-blue); box-shadow: 0 0 0 1px var(--accent-blue); }
.broker-card-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: var(--spacing-md);
}
.broker-logo {
  width: 48px; height: 48px; border-radius: var(--radius-md);
  background: var(--bg-tertiary); display: flex; align-items: center; justify-content: center;
  font-weight: 800; font-size: var(--font-sm); color: var(--accent-blue);
}
.broker-tier {
  font-size: var(--font-xs); font-weight: 600; padding: 3px 10px;
  border-radius: 20px; text-transform: uppercase; letter-spacing: 0.5px;
}
.tier-platinum { background: rgba(0,188,212,0.15); color: var(--teal); }
.tier-gold { background: var(--gold-bg); color: var(--gold); }
.tier-silver { background: rgba(158,158,158,0.15); color: #9e9e9e; }
.broker-name { font-size: var(--font-lg); font-weight: 700; margin-bottom: var(--spacing-sm); }
.broker-stats { display: flex; gap: var(--spacing-lg); margin-bottom: var(--spacing-md); }
.broker-stat { text-align: center; }
.broker-stat .bs-val { font-size: var(--font-xl); font-weight: 700; }
.broker-stat .bs-lbl { font-size: var(--font-xs); color: var(--text-muted); }
.broker-rating { display: flex; align-items: center; gap: var(--spacing-sm); margin-bottom: var(--spacing-sm); }
.stars { color: var(--gold); font-size: var(--font-lg); }
.broker-promo {
  background: var(--accent-blue-bg); color: var(--accent-blue);
  padding: 6px 12px; border-radius: var(--radius-sm); font-size: var(--font-xs); font-weight: 600;
  text-align: center; margin-top: var(--spacing-sm);
}

/* ===== Stats Banner ===== */
.stats-banner {
  background: linear-gradient(135deg, var(--accent-blue), #4a00e0);
  padding: var(--spacing-xl); border-radius: var(--radius-lg);
  display: flex; justify-content: space-around; text-align: center;
  margin: var(--spacing-2xl) 0;
}
.stats-banner .stat-num { font-size: var(--font-4xl); font-weight: 800; color: #fff; }
.stats-banner .stat-label { color: rgba(255,255,255,0.8); font-size: var(--font-md); }

/* ===== Filters Bar ===== */
.filters-bar {
  display: flex; align-items: center; gap: var(--spacing-md);
  flex-wrap: wrap; padding: var(--spacing-md) 0;
  border-bottom: 1px solid var(--border-color); margin-bottom: var(--spacing-lg);
}

/* ===== Pagination ===== */
.pagination {
  display: flex; align-items: center; justify-content: center;
  gap: var(--spacing-sm); padding: var(--spacing-xl) 0;
}
.pagination button {
  width: 36px; height: 36px; border-radius: var(--radius-md); border: 1px solid var(--border-color);
  background: var(--bg-card); color: var(--text-primary); cursor: pointer;
  font-family: inherit; font-size: var(--font-sm); transition: all 0.15s;
}
.pagination button:hover { border-color: var(--accent-blue); color: var(--accent-blue); }
.pagination button.active { background: var(--accent-blue); border-color: var(--accent-blue); color: #fff; }

/* ===== Mini Chart Cards ===== */
.minichart-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-md); padding: var(--spacing-md);
  display: flex; align-items: center; gap: var(--spacing-md);
  cursor: pointer; transition: all 0.15s;
}
.minichart-card:hover { border-color: var(--border-light); }
.minichart-info { flex: 1; min-width: 0; }
.minichart-name { font-weight: 600; font-size: var(--font-md); }
.minichart-price { font-size: var(--font-lg); font-weight: 700; }
.minichart-change { font-size: var(--font-xs); }
.minichart-graph { width: 100px; height: 40px; flex-shrink: 0; }

/* ===== Earnings Calendar ===== */
.earnings-row {
  display: grid; grid-template-columns: 100px 1fr 80px 80px; padding: 10px 14px;
  border-bottom: 1px solid var(--border-color); align-items: center; font-size: var(--font-md);
}
.earnings-row:hover { background: var(--bg-hover); }
.earnings-date { font-size: var(--font-sm); color: var(--text-muted); }
.earnings-company { font-weight: 600; }
.earnings-actual { text-align: right; font-variant-numeric: tabular-nums; }
.earnings-estimate { text-align: right; font-variant-numeric: tabular-nums; color: var(--text-muted); }

/* ===== Gainers/Losers ===== */
.mover-row {
  display: flex; align-items: center; justify-content: space-between;
  padding: 8px 0; border-bottom: 1px solid var(--border-color); font-size: var(--font-md);
}
.mover-name { font-weight: 500; }
.mover-change { font-weight: 600; }

/* ===== Story Cards ===== */
.story-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: var(--spacing-lg); transition: all 0.15s;
}
.story-card:hover { border-color: var(--border-light); }
.story-source { font-size: var(--font-xs); color: var(--text-muted); margin-bottom: var(--spacing-sm); }
.story-title { font-size: var(--font-md); font-weight: 600; margin-bottom: var(--spacing-sm); line-height: 1.4; }
.story-excerpt { font-size: var(--font-sm); color: var(--text-secondary); line-height: 1.5; }

/* ===== Toggle Switch ===== */
.toggle-wrap {
  display: flex; align-items: center; gap: var(--spacing-sm); font-size: var(--font-sm);
  color: var(--text-secondary); cursor: pointer;
}
.toggle {
  position: relative; width: 36px; height: 20px; background: var(--bg-tertiary);
  border-radius: 10px; transition: background 0.2s; cursor: pointer;
}
.toggle::after {
  content: ''; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px;
  background: var(--text-muted); border-radius: 50%; transition: all 0.2s;
}
.toggle.active { background: var(--accent-blue); }
.toggle.active::after { left: 18px; background: #fff; }

/* ===== Tooltip ===== */
.tooltip {
  position: absolute; background: var(--bg-card); border: 1px solid var(--border-color);
  padding: 8px 12px; border-radius: var(--radius-md); font-size: var(--font-sm);
  pointer-events: none; z-index: 200; box-shadow: var(--shadow-lg); display: none;
}

/* ===== Search ===== */
.search-box {
  display: flex; align-items: center; gap: var(--spacing-sm);
  background: var(--bg-tertiary); border: 1px solid var(--border-color);
  border-radius: var(--radius-md); padding: 6px 12px;
}
.search-box input {
  background: transparent; border: none; color: var(--text-primary);
  font-size: var(--font-sm); outline: none; width: 160px; font-family: inherit;
}
.search-box input::placeholder { color: var(--text-muted); }

/* ===== Indicators List ===== */
.indicator-row {
  display: flex; align-items: center; gap: var(--spacing-md);
  padding: 10px 0; border-bottom: 1px solid var(--border-color);
}
.indicator-icon {
  width: 36px; height: 36px; border-radius: var(--radius-md);
  background: var(--accent-blue-bg); display: flex; align-items: center; justify-content: center;
  color: var(--accent-blue); font-weight: 700; font-size: var(--font-xs); flex-shrink: 0;
}
.indicator-info { flex: 1; }
.indicator-name { font-weight: 600; font-size: var(--font-md); }
.indicator-desc { font-size: var(--font-sm); color: var(--text-secondary); }

/* ===== Footer ===== */
.main-footer {
  background: var(--bg-secondary); border-top: 1px solid var(--border-color);
  padding: var(--spacing-2xl) 0;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: var(--spacing-xl);
}
.footer-col h4 { font-size: var(--font-sm); font-weight: 600; margin-bottom: var(--spacing-md); color: var(--text-primary); text-transform: uppercase; letter-spacing: 0.5px; }
.footer-col a { display: block; font-size: var(--font-sm); color: var(--text-muted); padding: 4px 0; }
.footer-col a:hover { color: var(--text-primary); text-decoration: none; }
.footer-bottom {
  border-top: 1px solid var(--border-color); margin-top: var(--spacing-xl);
  padding-top: var(--spacing-lg); display: flex; justify-content: space-between;
  font-size: var(--font-sm); color: var(--text-muted);
}

/* ===== Dividers ===== */
.divider { border: none; border-top: 1px solid var(--border-color); margin: var(--spacing-lg) 0; }

/* ===== Empty State ===== */
.empty-state { text-align: center; padding: var(--spacing-2xl); color: var(--text-muted); }

/* ===== Badge ===== */
.badge {
  display: inline-block; padding: 2px 8px; border-radius: var(--radius-sm);
  font-size: var(--font-xs); font-weight: 600;
}

/* ===== Flex utilities ===== */
.flex { display: flex; }
.flex-wrap { flex-wrap: wrap; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-sm { gap: var(--spacing-sm); }
.gap-md { gap: var(--spacing-md); }
.gap-lg { gap: var(--spacing-lg); }
.mb-sm { margin-bottom: var(--spacing-sm); }
.mb-md { margin-bottom: var(--spacing-md); }
.mb-lg { margin-bottom: var(--spacing-lg); }
.mt-sm { margin-top: var(--spacing-sm); }
.mt-md { margin-top: var(--spacing-md); }
.mt-lg { margin-top: var(--spacing-lg); }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .chart-workspace { grid-template-columns: 1fr; }
  .chart-sidebar { display: none; }
  .chart-sidebar.mobile-open { display: flex; position: fixed; top: 56px; left: 0; bottom: 0; z-index: 50; width: 280px; }
  .stat-grid { grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); }
  .idea-grid { grid-template-columns: 1fr; }
  .broker-grid { grid-template-columns: 1fr; }
  .hero h1 { font-size: var(--font-3xl); }
}

@media (max-width: 768px) {
  .main-nav { display: none; }
  .header-inner { padding: 0 var(--spacing-md); }
  .container { padding: 0 var(--spacing-md); }
  .market-bar { font-size: var(--font-xs); }
  .stats-banner { flex-direction: column; gap: var(--spacing-lg); }
  .hero h1 { font-size: var(--font-2xl); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .section { padding: var(--spacing-lg) 0; }
  .filters-bar { flex-direction: column; align-items: flex-start; }
}

@media (max-width: 480px) {
  .btn { padding: 6px 12px; font-size: var(--font-sm); }
  .stat-grid { grid-template-columns: 1fr 1fr; }
}

