  // ===== Sparkline Charts =====
  window.drawSparkline = function(canvas, data, color) {
    if (!canvas) return;
    var ctx = canvas.getContext('2d');
    var w = canvas.width = canvas.offsetWidth || 80;
    var h = canvas.height = canvas.offsetHeight || 30;
